'use strict';
/**
 * Database layer: SQLite (better-sqlite3) with WAL, foreign keys and a
 * schema that is portable to PostgreSQL. All timestamps are ISO-8601 UTC
 * strings generated by the application (never by DB defaults) so behaviour
 * is identical across engines.
 */
const path = require('path');
const fs = require('fs');
const Database = require('better-sqlite3');

const DATA_DIR = path.resolve(process.env.DATA_DIR || path.join(__dirname, '..', 'data'));
fs.mkdirSync(DATA_DIR, { recursive: true });
fs.mkdirSync(path.join(DATA_DIR, 'uploads'), { recursive: true });

const DB_FILE = process.env.DB_FILE || path.join(DATA_DIR, 'attendance.db');
const db = new Database(DB_FILE);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');
db.pragma('busy_timeout = 5000');

const SCHEMA = `
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('admin','teacher')),
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT
);

CREATE TABLE IF NOT EXISTS sessions (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  csrf TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  ip TEXT,
  user_agent TEXT
);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_exp ON sessions(expires_at);

CREATE TABLE IF NOT EXISTS password_resets (
  token_hash TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  used INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS departments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL UNIQUE,
  code TEXT NOT NULL UNIQUE COLLATE NOCASE,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS courses (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  code TEXT,
  department_id INTEGER NOT NULL REFERENCES departments(id),
  duration_years INTEGER NOT NULL DEFAULT 4,
  created_at TEXT NOT NULL,
  UNIQUE(name, department_id)
);

CREATE TABLE IF NOT EXISTS sections (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  department_id INTEGER NOT NULL REFERENCES departments(id),
  course_id INTEGER REFERENCES courses(id),
  semester INTEGER NOT NULL CHECK(semester BETWEEN 1 AND 12),
  batch TEXT,
  academic_year TEXT,
  created_at TEXT NOT NULL,
  UNIQUE(department_id, semester, name, academic_year)
);

CREATE TABLE IF NOT EXISTS students (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  enrollment_no TEXT NOT NULL UNIQUE COLLATE NOCASE,
  roll_no TEXT NOT NULL,
  full_name TEXT NOT NULL,
  dob TEXT,
  gender TEXT CHECK(gender IN ('male','female','other') OR gender IS NULL),
  department_id INTEGER NOT NULL REFERENCES departments(id),
  course_id INTEGER REFERENCES courses(id),
  semester INTEGER NOT NULL CHECK(semester BETWEEN 1 AND 12),
  section_id INTEGER NOT NULL REFERENCES sections(id),
  batch TEXT,
  email TEXT,
  phone TEXT,
  parent_name TEXT,
  parent_phone TEXT,
  parent_email TEXT,
  admission_year INTEGER,
  joined_date TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','graduated','transferred')),
  created_at TEXT NOT NULL,
  updated_at TEXT,
  deleted_at TEXT,
  UNIQUE(section_id, roll_no)
);
CREATE INDEX IF NOT EXISTS idx_students_section ON students(section_id);
CREATE INDEX IF NOT EXISTS idx_students_dept_sem ON students(department_id, semester);
CREATE INDEX IF NOT EXISTS idx_students_name ON students(full_name);
CREATE INDEX IF NOT EXISTS idx_students_status ON students(status);
CREATE INDEX IF NOT EXISTS idx_students_roll ON students(roll_no);

CREATE TABLE IF NOT EXISTS subjects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  department_id INTEGER NOT NULL REFERENCES departments(id),
  semester INTEGER NOT NULL,
  section_id INTEGER NOT NULL REFERENCES sections(id),
  teacher_id INTEGER REFERENCES users(id),
  credits INTEGER NOT NULL DEFAULT 3 CHECK(credits BETWEEN 0 AND 30),
  total_classes INTEGER NOT NULL DEFAULT 0 CHECK(total_classes >= 0),
  academic_year TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),
  created_at TEXT NOT NULL,
  UNIQUE(code, section_id)
);
CREATE INDEX IF NOT EXISTS idx_subjects_teacher ON subjects(teacher_id);
CREATE INDEX IF NOT EXISTS idx_subjects_section ON subjects(section_id);

CREATE TABLE IF NOT EXISTS attendance_records (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER NOT NULL REFERENCES students(id),
  subject_id INTEGER NOT NULL REFERENCES subjects(id),
  date TEXT NOT NULL,
  period INTEGER NOT NULL DEFAULT 1 CHECK(period BETWEEN 1 AND 12),
  status TEXT NOT NULL CHECK(status IN ('P','A','E','H','C')),
  source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','import')),
  created_by INTEGER REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT,
  UNIQUE(student_id, subject_id, date, period)
);
CREATE INDEX IF NOT EXISTS idx_att_date ON attendance_records(date);
CREATE INDEX IF NOT EXISTS idx_att_student ON attendance_records(student_id, subject_id);
CREATE INDEX IF NOT EXISTS idx_att_subject_date ON attendance_records(subject_id, date);
CREATE INDEX IF NOT EXISTS idx_att_status ON attendance_records(status);

CREATE TABLE IF NOT EXISTS attendance_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  record_id INTEGER,
  student_id INTEGER NOT NULL,
  subject_id INTEGER NOT NULL,
  date TEXT NOT NULL,
  period INTEGER NOT NULL,
  old_status TEXT,
  new_status TEXT,
  reason TEXT,
  changed_by INTEGER REFERENCES users(id),
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_att_audit_student ON attendance_audit(student_id);

CREATE TABLE IF NOT EXISTS imports (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  filename TEXT NOT NULL,
  stored_name TEXT NOT NULL,
  file_hash TEXT NOT NULL,
  size INTEGER NOT NULL CHECK(size >= 0),
  subject_id INTEGER REFERENCES subjects(id),
  period INTEGER NOT NULL DEFAULT 1,
  uploaded_by INTEGER REFERENCES users(id),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK(status IN ('pending','reviewed','confirmed','cancelled','failed')),
  summary TEXT,
  created_at TEXT NOT NULL,
  confirmed_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_imports_hash ON imports(file_hash);

CREATE TABLE IF NOT EXISTS import_rows (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  import_id INTEGER NOT NULL REFERENCES imports(id) ON DELETE CASCADE,
  row_no INTEGER NOT NULL,
  raw TEXT,
  roll_no TEXT,
  name TEXT,
  date TEXT,
  status_value TEXT,
  student_id INTEGER REFERENCES students(id),
  match_status TEXT NOT NULL DEFAULT 'none' CHECK(match_status IN ('matched','possible','none')),
  match_candidates TEXT,
  validation TEXT NOT NULL DEFAULT 'valid'
    CHECK(validation IN ('valid','warning','error','needs_review')),
  issues TEXT,
  conflict_existing TEXT,
  action TEXT NOT NULL DEFAULT 'import' CHECK(action IN ('import','ignore'))
);
CREATE INDEX IF NOT EXISTS idx_import_rows_import ON import_rows(import_id);

CREATE TABLE IF NOT EXISTS settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS notification_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER NOT NULL REFERENCES students(id),
  subject_id INTEGER REFERENCES subjects(id),
  channel TEXT NOT NULL CHECK(channel IN ('email','sms','whatsapp')),
  recipient TEXT,
  message TEXT,
  attendance_bp INTEGER,
  type TEXT NOT NULL DEFAULT 'threshold' CHECK(type IN ('threshold','manual','digest')),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK(status IN ('pending','sent','delivered','failed','skipped')),
  provider TEXT,
  provider_response TEXT,
  error TEXT,
  rule TEXT,
  created_by INTEGER REFERENCES users(id),
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_notif_student ON notification_events(student_id);
CREATE INDEX IF NOT EXISTS idx_notif_status ON notification_events(status);
CREATE INDEX IF NOT EXISTS idx_notif_created ON notification_events(created_at);

CREATE TABLE IF NOT EXISTS notification_state (
  student_id INTEGER NOT NULL REFERENCES students(id),
  subject_id INTEGER NOT NULL REFERENCES subjects(id),
  below INTEGER NOT NULL DEFAULT 0,
  last_pct_bp INTEGER,
  crossing_notified INTEGER NOT NULL DEFAULT 0,
  last_notified_at TEXT,
  last_attempt_at TEXT,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (student_id, subject_id)
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER REFERENCES users(id),
  action TEXT NOT NULL,
  entity TEXT,
  entity_id TEXT,
  old_value TEXT,
  new_value TEXT,
  ip TEXT,
  user_agent TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_action ON audit_logs(action);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at);
`;

db.exec(SCHEMA);

/* One-time migration: early dev builds had UNIQUE(import_id, row_no) on
   import_rows, which is invalid for matrix sheets (one source row expands to
   many date entries). Rebuild the table if that constraint exists. */
(() => {
  const row = db.prepare(`SELECT sql FROM sqlite_master WHERE type='table' AND name='import_rows'`).get();
  if (row && /UNIQUE\s*\(\s*import_id\s*,\s*row_no\s*\)/i.test(row.sql)) {
    db.exec(`
      BEGIN IMMEDIATE;
      CREATE TABLE import_rows_mig (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        import_id INTEGER NOT NULL REFERENCES imports(id) ON DELETE CASCADE,
        row_no INTEGER NOT NULL,
        raw TEXT, roll_no TEXT, name TEXT, date TEXT, status_value TEXT,
        student_id INTEGER REFERENCES students(id),
        match_status TEXT NOT NULL DEFAULT 'none' CHECK(match_status IN ('matched','possible','none')),
        match_candidates TEXT,
        validation TEXT NOT NULL DEFAULT 'valid'
          CHECK(validation IN ('valid','warning','error','needs_review')),
        issues TEXT, conflict_existing TEXT,
        action TEXT NOT NULL DEFAULT 'import' CHECK(action IN ('import','ignore'))
      );
      INSERT INTO import_rows_mig SELECT * FROM import_rows;
      DROP TABLE import_rows;
      ALTER TABLE import_rows_mig RENAME TO import_rows;
      CREATE INDEX IF NOT EXISTS idx_import_rows_import ON import_rows(import_id);
      COMMIT;`);
  }
})();

/** Run fn inside an immediate transaction; roll back on any error. */
function withTx(fn) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    try { db.exec('ROLLBACK'); } catch { /* already rolled back */ }
    throw err;
  }
}

const getSetting = (key, fallback = null) => {
  const r = db.prepare('SELECT value FROM settings WHERE key = ?').get(key);
  return r ? r.value : fallback;
};
const setSetting = (key, value) => {
  db.prepare(`INSERT INTO settings(key, value) VALUES(?, ?)
              ON CONFLICT(key) DO UPDATE SET value = excluded.value`).run(key, String(value));
};
const allSettings = () => {
  const out = {};
  for (const r of db.prepare('SELECT key, value FROM settings').all()) out[r.key] = r.value;
  return out;
};
const getSettingInt = (key, fallback) => {
  const v = Number.parseInt(getSetting(key, ''), 10);
  return Number.isFinite(v) ? v : fallback;
};

module.exports = { db, withTx, getSetting, setSetting, allSettings, getSettingInt, DATA_DIR, DB_FILE };
